import { test, expect } from '@playwright/test';

test('拦截并 mock API', async ({ page }) => {
  // 拦截 /api/todos 请求并返回固定数据
  await page.route('**/api/todos', async route => {
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify([
        { id: 1, text: 'Playwright 学习', done: false },
        { id: 2, text: '写自动化测试', done: true },
      ]),
    });
  });

  await page.goto('https://example-todo-app.com');
  const items = await page.locator('.todo-item').allTextContents();
  console.log('加载到的待办事项:', items);

  // 断言 UI 显示 mock 数据
  await expect(page.locator('.todo-item')).toHaveCount(2);
  await expect(page.locator('.todo-item').first()).toContainText('Playwright 学习');
});

test('拦截所有图片请求', async ({ page }) => {
  // 拦截所有 PNG 和 JPEG 图片
  await page.route('**/*.{png,jpg,jpeg}', route => route.abort());

  // 导航到页面（图片不会被加载）
  await page.goto('https://www.runoob.com/');
  // 页面可能加载更快，因为没有下载图片
});

test('监控网络请求', async ({ page }) => {
  const requests = [];

  // 监听所有请求
  page.on('request', request => {
    requests.push({
      url: request.url(),
      method: request.method(),
      postData: request.postData(),
    });
  });

  await page.goto('https://www.runoob.com/');

  // 打印所有请求
  console.log('页面共发起了', requests.length, '个请求');
  requests.forEach(r => console.log(r.method, r.url));
});

// 文件路径：playwright.config.ts
export default defineConfig({
  fullyParallel: true,  // 同一文件内的测试也并行运行
});

// 文件路径：pages/LoginPage.ts
import { type Page, type Locator, expect } from '@playwright/test';

export class LoginPage {
  readonly page: Page;
  // 将所有定位器声明为只读属性
  readonly usernameInput: Locator;
  readonly passwordInput: Locator;
  readonly loginButton: Locator;
  readonly errorMessage: Locator;

  constructor(page: Page) {
    this.page = page;
    // 在构造函数中初始化所有定位器
    this.usernameInput = page.getByLabel('用户名');
    this.passwordInput = page.getByLabel('密码');
    this.loginButton = page.getByRole('button', { name: '登录' });
    this.errorMessage = page.getByTestId('login-error');
  }

  // 导航到登录页
  async goto() {
    await this.page.goto('/login');
  }

  // 执行登录操作
  async login(username: string, password: string) {
    await this.usernameInput.fill(username);
    await this.passwordInput.fill(password);
    await this.loginButton.click();
  }

  // 验证登录失败的错误提示
  async expectLoginError(message: string) {
    await expect(this.errorMessage).toBeVisible();
    await expect(this.errorMessage).toContainText(message);
  }
}

