// playwright.config.ts
import { defineConfig, devices } from '@playwright/test';

export default defineConfig({
  testDir: './tests',
  timeout: 30_000,
  retries: 2,
  workers: 4,
  reporter: [['html', { outputFolder: 'report' }], ['list']],
  forbidOnly: !!process.env.CI,

  // 统一默认使用（可在项目或测试级覆盖）
  use: {
    baseURL: 'https://demo.playwright.dev',
    headless: true,
    screenshot: 'only-on-failure',
    video: 'retain-on-failure',
    trace: 'retain-on-failure',
    viewport: { width: 1366, height: 900 },
    locale: 'zh-CN',
  },

  // 多项目：不同浏览器/设备/登录态
  projects: [
    { name: 'Chromium', use: { ...devices['Desktop Chrome'] } },
    { name: 'Firefox',  use: { ...devices['Desktop Firefox'] } },
    {
      name: 'Mobile Chrome',
      use: { ...devices['Pixel 7'], headless: true },
    },
    // 带登录态项目（复用 storageState）
    {
      name: 'Chromium Logged-in',
      use: { storageState: 'storageState.json' },
      dependencies: ['setup'], // 依赖前置项目生成登录态
    },
    // 前置"setup"项目：只跑一次生成 storageState
    {
      name: 'setup',
      testMatch: /auth\.setup\.ts/,
    },
  ],
});

test('RUNOOB 首页视觉回归', async ({ page }) => {
  await page.goto('https://www.runoob.com/');

  // 首次运行：保存基准截图
  // 后续运行：与基准截图对比
  await expect(page).toHaveScreenshot('runoob-homepage.png');
});

// 创建 Locator（此时不会查找元素）
const btn = page.getByRole('button', { name: '延迟出现的按钮' });

// 点击时自动等待按钮出现（最多等待 action timeout 时间）
await btn.click();
